import os
import re
import sys
import time
import logging
import random
from ute_common_abstract_core import logger as core_logger
from taf.launcher.ue_proxy_mngr_fastmile.config import Config
from taf.launcher.ue_proxy_mngr_fastmile.shell import Shell
from taf.launcher.ue_proxy_mngr_fastmile.exceptions import (NoFreePortException, UeproxyMngrStartFailure,
                                                            InvalidNmapCommandParameters)


class Launcher(object):
    """A class that represents a launcher for the ueproxy mngr service.

    The Launcher class provides methods to start and stop the ueproxy mngr service,
    generate the ueproxy configuration file, and perform various utility functions
    related to the ueproxy mngr service.

    Attributes:
        START_CMD (str): The command used to start the ueproxy mngr service.
        STOP_CMD (str): The command used to stop the ueproxy mngr service.
        UEPROXY_CONFIG_FILE (str): The path to the ueproxy configuration file.
        MIN_UEPROXY_PORT (int): The minimum port number for ueproxy.
        MAX_UEPROXY_PORT (int): The maximum port number for ueproxy.
        UEPROXY_PORT_SEARCH_ATTEMPTS (int): The number of attempts to find a free port for ueproxy.
    """
    START_CMD = ("cd {ueproxy_logs_dir};{python_path} -m "
                 "taf.ue.proxy.mngr.run_ue_proxy_mngr --port {port} "
                 "--ueproxy_ports_range {port_range} "
                 "--ueproxy_config {cfg_file} >/dev/null 2>&1 &")
    STOP_CMD = "kill {pids}"
    UEPROXY_CONFIG_FILE = '/tmp/ueproxy_config/proxy.cfg'
    MIN_UEPROXY_PORT = 8100
    MAX_UEPROXY_PORT = 8200
    UEPROXY_PORT_SEARCH_ATTEMPTS = 100

    def __init__(self, config, logger=None):
        """Initializes a new instance of the Launcher class.

        Args:
            config (dict): The configuration for the ueproxy mngr service.
        """
        self.logger = logger or logging.getLogger("ueproxy_mngr_fastmile_launcher")
        self.ueproxy_config = Config(self.logger).get_config(config)
        self.shell = Shell(self.logger)
        self.ueproxy_mngr_port_list = []
        self.proxy_mngr_params = []
        self.cached_local_ips = None
        self._filter_proxy_mngr_params()

    @property
    def default_python_path(self):
        """str: The default python path for ueproxy."""
        return sys.executable

    @property
    def default_ueproxy_logs_dir(self):
        """str: The default directory for ueproxy logs."""
        return core_logger.get_logging_path() + "/"

    @property
    def ueproxy_trials(self):
        """int: The number of trails for ueproxy."""
        return self.ueproxy_config.get('ueproxy_trials', 5)

    @property
    def ueproxy_interval(self):
        """int: The interval between ueproxy requests."""
        return self.ueproxy_config.get('ueproxy_interval', 3)

    @property
    def heartbeat_interval(self):
        """int: The interval between heartbeat requests."""
        return self.ueproxy_config.get('heartbeat_interval', 2)

    @property
    def heartbeat_ip(self):
        """str: The IP address for heartbeat requests."""
        return self.ueproxy_config.get('heartbeat_ip')

    def _get_ips(self):
        """Gets the list of valid IP addresses for ueproxy mngr.

        Returns:
            str: A comma-separated string of valid IP addresses.
        """
        valid_ips_list = []
        for ips in self.proxy_mngr_params:
            valid_ips_list.append(ips.get('ue_manage_ip'))
            # if self._is_ueproxy_mngr_running(ue_pc_address, proxy_mngr_port):
        return list(set(valid_ips_list))

    def _get_ueproxy_ports_range(self):
        """Gets the ueproxy ports range.

        Returns:
            str: The ueproxy ports range in the format "min_port max_port".
        """
        free_port = self._find_random_free_port(self.MIN_UEPROXY_PORT,
                                                self.MAX_UEPROXY_PORT,
                                                self.UEPROXY_PORT_SEARCH_ATTEMPTS)
        self.logger.debug('{!r}: chosen port {}.'.format(self, free_port))
        return f"{free_port} {free_port}"

    def _get_ueproxy_mngr_port(self):
        """Gets the ueproxy mngr port.

        Returns:
            int: The ueproxy mngr port.

        Raises:
            ValueError: If the ueproxy mngr port is not defined or not unique.
        """
        if len(self.ueproxy_mngr_port_list) == 0:
            raise ValueError("ueproxy mngr port is not defined.")
        elif len(self.ueproxy_mngr_port_list) == 1:
            return self.ueproxy_mngr_port_list[0]
        raise ValueError(f"ueproxy mngr port must be unique: {self.ueproxy_mngr_port_list}")

    def _filter_proxy_mngr_params(self):
        """Filters the proxy mngr parameters based on localhost addresses."""
        for ips in self.ueproxy_config.get('ips', []):
            ue_pc_address = ips.get('ue_pc_address')
            proxy_mngr_port = ips.get('proxy_mngr_port')
            if proxy_mngr_port and self._is_localhost(ue_pc_address):
                self.ueproxy_mngr_port_list.append(proxy_mngr_port)
                self.proxy_mngr_params.append(ips)
        self.ueproxy_mngr_port_list = list(set(self.ueproxy_mngr_port_list))

    def _generate_ueproxy_config_file(self, file_path=None):
        """Generates the ueproxy configuration file.

        Args:
            file_path (str, optional): The path of the file to write to.
                If not specified, the default ueproxy configuration file path is used.
        """
        file_path = file_path or self.UEPROXY_CONFIG_FILE
        self.shell.remove_file(file_path)
        self.shell.mkdir(os.path.dirname(file_path))
        with open(file_path, 'w') as file:
            # UE GATEWAYS part
            file.write("[UE GATEWAYS]\n")
            file.write(f"ips = {','.join(self._get_ips())}\n")
            file.write(f"trials = {self.ueproxy_trials}\n")
            file.write(f"interval = {self.ueproxy_interval}\n\n")

            # HEARTBEAT part
            file.write("[HEARTBEAT]\n")
            file.write(f"interval = {self.heartbeat_interval}\n")
            file.write(f"address = {self.heartbeat_ip}\n")
        return file_path

    def start_ueproxy_mngr(self, wait_time=2):
        """
        Starts the ueproxy mngr service.

        Args:
            wait_time (int): The time to wait before checking if UE Proxy Manager started. Default is 2 seconds.
        """
        if self._is_ueproxy_mngr_running():
            self.logger.warning("ueproxy mngr service is already in use, skip to start ueproxy mngr.")
            return
        command = self.START_CMD.format(ueproxy_logs_dir=self.default_ueproxy_logs_dir,
                                        python_path=self.default_python_path,
                                        port=self._get_ueproxy_mngr_port(),
                                        port_range=self._get_ueproxy_ports_range(),
                                        cfg_file=self._generate_ueproxy_config_file())
        self.logger.debug(f"Starting ueproxy mngr with command: {command}")
        result = self.shell.execute(command)
        # Wait for the ueproxy mngr service to start successfully or fail
        time.sleep(wait_time)
        if not self._is_ueproxy_mngr_running():
            raise UeproxyMngrStartFailure(f"start ueproxy mngr service failed with exception '{result}'.")

    def stop_ueproxy_mngr(self):
        """Stops the ueproxy mngr service."""
        pids = self._get_pids()
        if pids:
            self.logger.info(f"Stopping ueproxy mngr processes with PIDs: {pids}.")
            command = self.STOP_CMD.format(pids=pids)
            self.shell.execute(command)
        else:
            self.logger.info("No ueproxy mngr process found to stop.")

    def _get_pids(self):
        """Gets the process IDs (PIDs) of the ueproxy mngr processes.

        Returns:
            str: A space-separated string of PIDs.
        """
        query_pid_command = f"ss -ltnp | grep :{self._get_ueproxy_mngr_port()}"
        output = self.shell.execute(query_pid_command)
        pids = re.findall(rf'{self._get_ueproxy_mngr_port()}.*"python",pid=(\d+),', output)
        return ' '.join(set(pids))

    def _is_ueproxy_mngr_running(self):
        """Checks if the ueproxy mngr service is running.

        Returns:
            bool: True if the ueproxy mngr service is running, False otherwise.
        """
        for ips in self.proxy_mngr_params:
            is_port_free = self._is_port_free_in_nmap(ips['ue_pc_address'],
                                                      ips['proxy_mngr_port'])
            port_state_msg = "free" if is_port_free else "already in use"
            self.logger.debug(f"ueproxy mngr port {ips['proxy_mngr_port']} is {port_state_msg}.")
            if not is_port_free:
                return True
        return False

    def _is_localhost(self, address):
        """Checks if the given address is a localhost address.

        Args:
            address (str): The address to check.

        Returns:
            bool: True if the address is a localhost address, False otherwise.
        """
        if self.cached_local_ips is None:
            command = "ip addr | grep -w inet"
            output = self.shell.execute(command)
            self.cached_local_ips = output
        if address in self.cached_local_ips:
            self.logger.info(f'"{address}" in ueproxy mngr host address list: "{self.cached_local_ips}"')
            return True
        self.logger.info(f'"{address}" not in ueproxy mngr host address list: "{self.cached_local_ips}"')
        return False

    def _is_port_free_in_nmap(self, address, port):
        """Checks if the given port is free using nmap.

        Args:
            address (str): The IP address to check.
            port (int): The port number to check.

        Returns:
            bool: True if the port is free, False otherwise.
        """
        command = f"nmap -p {port} {address}"
        output = self.shell.execute(command)

        pattern = r"(\d{1,3}(?:\.\d{1,3}){3})[\s\S]*\n(\d+)/tcp\s+(\w+)\s+"
        match = re.search(pattern, output)
        if match:
            self.logger.info(f"nmap result: {match.groups()}.")
            ip_address = match.group(1)
            tcp_port = match.group(2)
            state = match.group(3)
            self.logger.info(f'port {port} state: "{ip_address}_{tcp_port}_{state}"')
            return tcp_port == str(port) and state == 'closed'
        raise InvalidNmapCommandParameters(f"nmap command parameters is invalid with exception '{output}'.")

    def _find_random_free_port(self, min_port, max_port, attempts=3):
        """Finds a random free TCP port within the specified range.

        Args:
            min_port (int): The minimum port number to search.
            max_port (int): The maximum port number to search.
            attempts (int, optional): The number of attempts to find a free port.
                Defaults to 3.

        Returns:
            int: The free port number.

        Raises:
            NoFreePortException: If no free port is found within the specified attempts.
        """
        self.logger.debug("Starting free port search in range {}-{}.".format(min_port, max_port))
        for attempt in range(attempts):
            port = random.randint(min_port, max_port)
            is_port_free = self._is_port_free_in_nmap("127.0.0.1", port)
            port_state_msg = "free" if is_port_free else "already in use"
            self.logger.debug(f"Search attempt {attempt}. Port {port} is {port_state_msg}.")
            if is_port_free:
                return port
        raise NoFreePortException("No free port was found in {} attempts".format(attempts))
